@module tuning  src=tuning.lua  loc=488  mode=namespace  self=tuning

# Invariants & contracts
  @invariant  pure coordinate-system module: no module state, no take state, no pb / detune realisation logic  @ 4
  @invariant  intent / realisation split — owns intent (cents-typed detune); pb realisation is tm's domain  @ 5
  @invariant  detune is cents throughout; raw 14-bit pb conversion is tm's flush boundary, never here  @ 6
  @invariant  cents[1] is the unison (0); nameless step displays as degree-octave via stepToParts  @ 7
  @invariant  an octave is period-index + octaveBase; default root makes it MIDI-relative (C4 → 4)  @ 8

# Shapes
  @shape  Temper = {name, periodPitch=token, pitches=token[ascending], stepNames=string[], periodAsStep=bool, rootPitch=int?, rootDetune=cents?, rootStep=int?, rootOctave=int?, cents=number[derived], period=cents[derived], rootCents=cents[derived], octaveBase=int[derived], octaveStep=int, octaveWidth=int, cellWidth=int}  @ 9

# Imports
  @const util = 'util'  @ 10

# Module-level constants
  @const tuning = {}  @ 12
  @const RATIO_CAP = 1 << 40  @ 335
  @const MIDI_NAMES = { 'C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', '...  @ 473

# Private functions
  -- Temperament presets
  @fn computeOctaveStep(stepNames, n)  @ 18-24
      -- octaveStep: first step whose label reads as the next octave's C. Scans from
      -- the end for the last non-C name; nameless scale → bump at period (n+1).
  @fn octaveLabel(o)  @ 28-30
      -- A negative octave renders as its magnitude, for the caller to tint — the
      -- sign costs no column. See docs/tuning.md § Display.
  @fn octaveFieldWidth(temper)  @ 34-39
      -- octaveFieldWidth: char width of the octave field, sized on the octave
      -- numbers at both ends of the range the root opens. See docs/tuning.md § Display.
  @fn computeRootCents(temper)  @ 43-46
      -- rootCents: where the scale's unison sits in sound, given the root's four
      -- authored fields. See docs/tuning.md § The root.
  @fn computeCellWidth(temper)  @ 49-58
      -- cellWidth: widest step label + the octave field; see docs/tuning.md § Display.
  @fn edo(n, names)  @ 107-116
  -- Scala import
  -- Generators
  @fn gcd(a, b)  @ 280
  @fn combinations(n, k)  @ 283-291
      -- Every k-subset of 1..n as a list of 1-based index lists.
  @fn reduceCents(c, period)  @ 322-324
      -- Reduce a cents value into [0, period).
  @fn asRatio(token)  @ 326-331
  @fn stackRatio(gn, gd, pn, pd, k)  @ 336-347
  @fn stepSpectrum(g, p, n)  @ 351-365
      -- Adjacent step sizes (incl. the wrap step) of an n-note chain of `g`
      -- reduced into `p`: {cents, count} per distinct size, large first.

# Public API (tuning.*)
  @api tuning.scalaPitch(token)  @ 61-79
      @contract  token → cents or nil: n/d, int, '.'=cents, n\m, n\m<equave> step (equave dflt 2/1).  @ 60
  @api tuning.derive(temper)  @ 82-98
      @contract  pitches→cents, periodPitch→period; stamps root/octave/cell fields. Pure; returns temper.  @ 81
  @api tuning.unrooted(temper)  @ 101-105
      @contract  copy with the four root fields dropped and stamps refreshed at the default root  @ 100
  @api tuning.findTemper(name, userLib)  @ 141-144
      @contract  userLib first, then presets; nil when unknown to both; '12EDO' resolves via presets  @ 140
  @api tuning.parseScalaPitches(text)  @ 150-157
      -- Lenient: every non-blank, non-'!' line is a pitch token. Drives paste + the
      -- import Create button (which re-parses the box after any manual edits).
  @api tuning.parseScalaFile(text)  @ 161-175
      -- Strict .scl: drop '!' comment lines, then [description, count, pitch x count].
      -- Returns pitch tokens + description (suggested name) for the Scala load path.
  @api tuning.scalaToTemper(pitchLines, name)  @ 179-197
      -- Bridge Scala's convention (unison implicit, period last) to Continuum's
      -- (step 1 = 1/1, period separate): prepend unison, split off final as period.
  @api tuning.edoDegrees(spec, mode)  @ 203-220
      -- Equal-division subset spec -> ascending degrees; largest is the period.
      -- 'relative': cumulative step counts. 'absolute': sorted+deduped. nil on bad token.
  @api tuning.degreesToSpec(degrees, mode)  @ 224-229
      -- Inverse of edoDegrees: render a degree list back as a spec string in `mode`.
      -- Lets a mode switch convert the in-flight pattern rather than reset it.
  @api tuning.genEqual(degrees, interval)  @ 233-239
      -- N-equal-divisions of `interval` subset to `degrees`; tokens are intensional
      -- (d\D<equave>, suffix omitted for octave). Base 0 implicit; last degree = period.
  @api tuning.genHarmonics(lo, hi)  @ 243-247
      -- Harmonic-series segment lo..hi: ratios m/lo rooted on the low harmonic, the
      -- top (hi/lo) the period.
  @api tuning.genSubharmonics(lo, hi)  @ 250-254
      -- Subharmonic (utonal) segment lo..hi: ratios hi/m ascending, top the period.
  @api tuning.parseChord(spec)  @ 258-267
      -- Colon/space-separated extended ratio (e.g. '4:5:6:7') -> positive integers,
      -- at least two. nil + message otherwise.
  @api tuning.genChord(members, invert)  @ 271-278
      -- Enumerate a chord as a scale rooted on its first note. otonal: ci/c1.
      -- inverted (utonal): ck/c(k+1-i). The last member is the period either way.
  @api tuning.genCPS(factors, k, equave)  @ 295-319
      -- Combination product set: every k-subset's product, rooted on the smallest
      -- product (so 1/1 is always present) and reduced into the equave; ascending.
  @api tuning.genRank2(generator, period, size, up)  @ 369-388
      -- Rank-2 scale: stack the generator `up` above and `size-1-up` below 1/1,
      -- reduce into period, sort. up = mode. Exact ratios if inputs rational, else cents.
  @api tuning.mosInfo(generator, period, n)  @ 391-395
      @contract  {isMos, large, small} for an n-note chain; large/small are L/s step counts when isMos  @ 390
  @api tuning.nextMosSize(generator, period, fromN, dir)  @ 398-406
      @contract  next MOS size (two step sizes) from fromN, stepping dir (+/-1); nil past the cap  @ 397
  -- Coordinate conversions
  @api tuning.midiToStep(temper, midi, detune)  @ 412-431
      @contract  detune optional (defaults 0); snaps to nearest scale point including the period boundary (rounds up to step 1 of next octave)  @ 410
      @contract  returned octave is period-index + temper.octaveBase (at the default root, C-1 → -1)  @ 411
  @api tuning.stepToMidi(temper, step, octave)  @ 434-450
      @contract  wraps out-of-range step by adjusting octave; clamps midi to 0..127 by folding overflow into detune (never silently drops)  @ 433
  @api tuning.snap(temper, midi, detune)  @ 452-454
  @api tuning.transposeStep(temper, midi, detune, n)  @ 457-460
      @contract  moves by n scale steps under temper, carrying the octave; n may be negative  @ 456
  @api tuning.stepsBetween(temper, aMidi, aDetune, bMidi, bDetune)  @ 463-467
      @contract  signed count of whole temper steps from note a to note b, each snapped to nearest step  @ 462
  -- Display
  @api tuning.midiName(pitch)  @ 476-478
      @contract  MIDI number → untempered twelve-name spelling (0 → 'C-1', 60 → 'C4')  @ 475
  @api tuning.stepToParts(temper, step, octave)  @ 481-486
      @contract  (note, octaveLabel=|octave|, negative); name or degree+'-'; octave+1 at octaveStep  @ 480

